import{_ as a,o as s,c as t,a2 as n}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"manual/getting-started.md","filePath":"manual/getting-started.md"}'),o={name:"manual/getting-started.md"};function i(l,e,r,p,d,c){return s(),t("div",null,[...e[0]||(e[0]=[n(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>From zero to an <code>oc&gt;</code> prompt in five minutes.</p><h2 id="_1-download" tabindex="-1">1. Download <a class="header-anchor" href="#_1-download" aria-label="Permalink to &quot;1. Download&quot;">​</a></h2><p>Grab the current release ISO from the <a href="https://cubestudio-dev.github.io/OpenCubeOS/" target="_blank" rel="noreferrer">downloads page</a> or the <a href="https://github.com/cubestudio-dev/OpenCubeOS/releases" target="_blank" rel="noreferrer">GitHub releases</a>:</p><ul><li><code>opencube-&lt;version&gt;.iso</code> - hybrid BIOS+UEFI bootable image (about 12 MiB)</li></ul><p>Verify the SHA256 against the value printed on the download page and in the release note:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>sha256sum opencube-&lt;version&gt;.iso</span></span></code></pre></div><h2 id="_2-boot-it-in-qemu" tabindex="-1">2. Boot it in QEMU <a class="header-anchor" href="#_2-boot-it-in-qemu" aria-label="Permalink to &quot;2. Boot it in QEMU&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -cdrom opencube-&lt;version&gt;.iso \\</span></span>
<span class="line"><span>    -netdev user,id=n1 -device e1000,netdev=n1 \\</span></span>
<span class="line"><span>    -serial mon:stdio</span></span></code></pre></div><p>What you will see:</p><ol><li>The GRUB menu: <em>Open Cube OS (slot ISO)</em> plus force-slot entries (A / B) - see <a href="./boot-modes.html">boot-modes</a>. It auto-boots in 5 s.</li><li>The kernel boot log: one <code>OK</code> line per subsystem as it comes up (multiboot2 handshake, long mode, framebuffer, IDT, PIT, keyboard, serial, PMM, VMM, heap, drivers, VFS, network, shell).</li><li>The banner: <code>Open Cube OS &lt;version&gt; ready. Type &#39;help&#39; for commands.</code></li><li>The prompt: <code>oc&gt; </code></li></ol><p>UEFI instead of legacy BIOS:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>qemu-system-x86_64 -m 512 -machine q35 \\</span></span>
<span class="line"><span>    -bios /usr/share/ovmf/OVMF.fd \\</span></span>
<span class="line"><span>    -cdrom opencube-&lt;version&gt;.iso -display none -serial mon:stdio</span></span></code></pre></div><h2 id="_3-first-commands" tabindex="-1">3. First commands <a class="header-anchor" href="#_3-first-commands" aria-label="Permalink to &quot;3. First commands&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; help              (short command list)</span></span>
<span class="line"><span>oc&gt; help -a           (all 233, alphabetical)</span></span>
<span class="line"><span>oc&gt; help -w           (grouped by work package)</span></span>
<span class="line"><span>oc&gt; uname -a          (version + build + tree)</span></span>
<span class="line"><span>oc&gt; dskstat           (block devices found)</span></span>
<span class="line"><span>oc&gt; dhcp              (bring up networking)</span></span>
<span class="line"><span>oc&gt; ping 10.0.2.2     (the QEMU gateway)</span></span>
<span class="line"><span>oc&gt; wget 10.0.2.2     (fetch the gateway&#39;s index page)</span></span>
<span class="line"><span>oc&gt; dns example.com   (resolve a name through the QEMU DNS forwarder)</span></span>
<span class="line"><span>oc&gt; health            (CPU / memory / tasks / IO at a glance)</span></span>
<span class="line"><span>oc&gt; dmesg             (kernel ring buffer)</span></span></code></pre></div><p>The full reference with every command on its own page: <a href="./commands/">commands</a>.</p><h2 id="_4-keyboard" tabindex="-1">4. Keyboard <a class="header-anchor" href="#_4-keyboard" aria-label="Permalink to &quot;4. Keyboard&quot;">​</a></h2><ul><li>The shell line editor supports history (up/down), <code>Ctrl+U</code> line kill, and editing within the line.</li><li>On real hardware a PS/2 keyboard is driven directly; over serial (COM1) every keystroke you type into <code>-serial mon:stdio</code> lands in the same input queue.</li><li>The TUI layer (<code>tui</code> command) is keyboard-driven: menus, forms and the desktop launcher - see <a href="./tui-guide.html">tui-guide</a>.</li></ul><h2 id="_5-files" tabindex="-1">5. Files <a class="header-anchor" href="#_5-files" aria-label="Permalink to &quot;5. Files&quot;">​</a></h2><p>The boot system ships a <code>ramfs</code> (in-memory filesystem). Files you create vanish on reboot unless you put them on a mounted volume:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>oc&gt; dskstat                    (list devices: ata0, usda..., nvme0...)</span></span>
<span class="line"><span>oc&gt; mkfs.fat32 ata0 confirm    (optional: format a scratch disk)</span></span>
<span class="line"><span>oc&gt; fatmount ata0 /mnt         (FAT32; exfat/ext4 equivalents exist)</span></span>
<span class="line"><span>oc&gt; write /mnt/hello.txt &quot;hi&quot;  (a persistent file)</span></span>
<span class="line"><span>oc&gt; cat /mnt/hello.txt</span></span></code></pre></div><p>The <code>/etc</code> volume is a small persistent FAT32 image the system mounts automatically when present - it carries <code>opencube.conf</code>, SSH host keys, the kernel log and crash dumps.</p><h2 id="_6-where-to-go-next" tabindex="-1">6. Where to go next <a class="header-anchor" href="#_6-where-to-go-next" aria-label="Permalink to &quot;6. Where to go next&quot;">​</a></h2><ul><li><a href="./shell-basics.html">shell-basics</a> - pipes, redirection, env, aliases, scripting</li><li><a href="./network.html">network</a> - the full networking walk-through</li><li><a href="./boot-modes.html">boot-modes</a> - A/B slots and what the GRUB menu does</li><li><a href="./update-ota.html">update-ota</a> - updating a running system</li><li><a href="./recovery.html">recovery</a> - the WinRE-style recovery workflow</li><li>Building from source: <a href="./../dev/build.html">../dev/build.md</a></li></ul>`,24)])])}const m=a(o,[["render",i]]);export{u as __pageData,m as default};
